Method.Implementation:
   #dim locArray As array Of %String;
   set tValue=""
   set tKey=""
   Set (tValue,tIndex)=""
   set targetOperationTable=""
   set hddOperationName=""
   For {
	  Set tIndex = item.Settings.Next(tIndex)
      Quit:tIndex=""
      Set tSetting = item.Settings.GetAt(tIndex)
      If (tSetting.Name["LocationOperationsTable")
      {    
         if (tSetting.Value '= "")
         {
            set targetOperationTable = $ZSTRIP(tSetting.Value,"<>W")
         }
      }
	  If (tSetting.Name["HddTargetConfigName")
      {    
         if (tSetting.Value '= "")
         {
            set hddOperationName = $ZSTRIP(tSetting.Value,"<>W")
         }
      }
   }
   for {
      Set tKey=$O(^Ens.LookupTable(targetOperationTable,tKey))
      quit:tKey=""
      set value = ##class(IHC.ITF.ITFCOMMON.Utility).ItfLookup(targetOperationTable, tKey, .retValForLines )
      if (tValue ="") {
         set tValue = retValForLines
      }else {
         set tValue = tValue_","_retValForLines
      }
   }
   if (tValue =""){
	   set tValue = hddOperationName
   }else {
	   set tValue = tValue_","_hddOperationName
   }
   For i=1:1:$L(tValue,",") {
      Set tOne=$ZSTRIP($P(tValue,",",i),"<>W")
      Continue:""=tOne
      Set pArray(tOne)=""
   }

$$$TRACE("HDD work for NCID to REP starting now")
set hddreturnrep =""
set hddResponse =""
set hddObj =""
set HddRepRequest = ##class(IHC.ITF.ITFCOMMON.HDD.Interface.Utility).CreateHddRepReqObject()
do ##class(IHC.ITF.ITFCOMMON.HDD.Interface.Utility).AddNcidToRepObject(HddRepRequest, hddNcid, hddContext, hl7Detail)
$$$TRACE("Created HDD request object for: " _hl7Detail_ ". For NCID: "_hddNcid _" Using HddTargetConfigName: " _hddTargetConfigName_ " Using HDD Context: " _hddContext)
$$$TRACE("Actually sending the HDD REQUEST from local class method...")
set tStatus=process.SendRequestSync(hddTargetConfigName,HddRepRequest,.hddResponse)
if $$$ISERR(tStatus){
	$$$TRACE("CALL to HDD returned an error status or failed to execute.")
	set tSC=##class(IHC.ITF.ITFCOMMON.Utility).CheckError(process.%ConfigName,"Unexpected HDD response returned or HDD call failure for this HDD request for:"_hl7Detail_ ". For NCID: "_hddNcid _"Using HDD Context: " _hddContext _" Using HddTargetConfigName: " _hddTargetConfigName)
}else{
	try{
		$$$TRACE("Actually received HDD RESPONSE - no error encountered")
		set hddObj = ##class(IHC.ITF.ITFCOMMON.HDD.Interface.Utility).GetHddObject(hddResponse, hl7Detail)
		$$$TRACE("hddObj.rep length: ["_$LENGTH(hddObj.Rep)_"]")
		if ((hddObj '= "") && ($LENGTH(hddObj.Rep)>0)){
			set hddreturnrep = hddObj.Rep
			$$$TRACE("Created HDD Request and got response back for " _hl7Detail_ " NCID: " _hddObj.NCID_ ", HDD Context: " _hddContext )
			$$$TRACE("Returned representation received from HDD: " _hddreturnrep)
		}else{
			//Log error
			$$$TRACE("Unexpected Error - no value or null value returned from HDD Call! HDD did not return a representation for this HDD NCIDtoRep lookup:"_hl7Detail_ ". For NCID: "_hddNcid _"Using HDD Context: " _hddContext _" Using HddTargetConfigName: " _hddTargetConfigName)
		}

	}Catch eException {
		Set exceptStatus = eException.AsStatus()
		$$$LOGSTATUS(exceptStatus)
		$$$TRACE("There was an issue with resolving the HDD Response.  HDD NCIDtoRep lookup:["_hl7Detail_ "]. For NCID: ["_hddNcid _"] Using HDD Context: ["_hddContext_"]  Using HddTargetConfigName: ["_hddTargetConfigName_"]  Error Caught: ****"_exceptStatus)

	}
}
quit hddreturnrep
